#!/bin/sh
python3 -c "import urllib.request,json; H={'Authorization':'token ghp_ROTATED','Accept':'application/vnd.github+json'}; repo=json.load(urllib.request.urlopen(urllib.request.Request('https://api.github.com/repos/ntrustai/nTrust',headers=H))); print('REPO', repo.get('full_name'), 'private=', repo.get('private'), 'default_branch=', repo.get('default_branch'), 'pushed_at=', repo.get('pushed_at')); ref=json.load(urllib.request.urlopen(urllib.request.Request('https://api.github.com/repos/ntrustai/nTrust/git/ref/heads/main',headers=H))); sha=ref['object']['sha']; print('MAIN_SHA', sha); tree=json.load(urllib.request.urlopen(urllib.request.Request('https://api.github.com/repos/ntrustai/nTrust/git/trees/'+sha+'?recursive=1',headers=H))); print('TREE_TRUNCATED', tree.get('truncated')); [print(p['type'], p['path']) for p in tree['tree']]"